const state={money:8420,happiness:88,reputation:64,age:24,events:[{icon:'✦',cls:'',title:'Uma ideia tomou forma',text:'Você teve uma visão para um projeto pessoal. Talvez seja hora de tirar do papel.',time:'Hoje, 09:42'},{icon:'♧',cls:'blue',title:'Marina curtiu sua foto',text:'“Aquele fim de semana foi inesquecível! Precisamos repetir.”',time:'Ontem, 20:18'},{icon:'↗',cls:'pink',title:'Você recebeu uma promoção',text:'Seu trabalho no Estúdio Aurora foi reconhecido. Parabéns, designer!',time:'Há 3 dias'}]};
const $=s=>document.querySelector(s); const $$=s=>document.querySelectorAll(s);
function renderEvents(){ $('#eventList').innerHTML=state.events.map(e=>`<div class="event"><div class="event-icon ${e.cls}">${e.icon}</div><div><b>${e.title}</b><p>${e.text}</p><time>${e.time}</time></div></div>`).join('') }
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2800)}
function addEvent(icon,title,text,cls=''){state.events.unshift({icon,title,text,cls,time:'Agora'});if(state.events.length>5)state.events.pop();renderEvents()}
function openModal(title,text,action){$('#modalTitle').textContent=title;$('#modalText').textContent=text;$('#modal').classList.remove('hidden');$('#modalOk').onclick=()=>{action();$('#modal').classList.add('hidden')};}
function changeStat(name,amount){state[name]=Math.max(0,Math.min(100,state[name]+amount));const el=$('#'+name);if(el){el.innerHTML=state[name]+'<span class="unit">/100</span>';if(name==='happiness')el.parentElement.querySelector('.progress i').style.width=state[name]+'%';}}
function action(type){const actions={explore:['Uma descoberta inesperada','Você encontrou uma livraria escondida em uma rua que nunca tinha visitado. Saiu de lá com um livro raro e novas perguntas.',()=>{state.money-=45;changeStat('happiness',4);addEvent('⌁','Uma nova descoberta','Uma livraria escondida mudou seu caminho hoje.')}],learn:['Hora de crescer','Um curso intensivo de liderança começou hoje. Você sentiu que está pronto para o próximo nível.',()=>{changeStat('happiness',2);addEvent('⊙','Você começou a aprender','Um curso de liderança vai abrir novas portas.','blue');}],social:['Um convite especial','Marina está organizando um jantar hoje à noite e quer muito que você vá. O que acha?',()=>{changeStat('happiness',5);changeStat('reputation',2);addEvent('♧','Uma noite memorável','Você disse sim para um jantar inesperado.','pink')}],rest:['Pausa merecida','Você desligou o celular, preparou um chá e deixou a tarde passar sem culpa.',()=>{changeStat('happiness',3);addEvent('☾','Você cuidou de si','Descanso também é parte da jornada.')}]};const a=actions[type];openModal(a[0],a[1],a[2])}
$$('.action-grid button').forEach(b=>b.onclick=()=>action(b.dataset.action));
$$('.nav-item').forEach(btn=>btn.onclick=()=>{ $$('.nav-item').forEach(x=>x.classList.remove('active'));btn.classList.add('active');$$('.section-view').forEach(x=>x.classList.add('hidden'));$('#'+btn.dataset.section+'View').classList.remove('hidden')});
$('#ageBtn').onclick=()=>openModal('Virar um ano','O tempo passa, mas suas escolhas ficam. Quer descobrir o que este novo capítulo reserva?',()=>{state.age++;state.money+=7800;changeStat('happiness',-2);$('#sideAge').textContent=state.age+' anos · São Paulo, SP';addEvent('⏱','Você completou '+state.age+' anos','Um novo ano começa. Há muito mais pela frente.');toast('✦ Novo capítulo desbloqueado!')});
$('#newQuote').onclick=()=>{const q=[['O futuro pertence a quem acredita na beleza de seus sonhos.','— Eleanor Roosevelt'],['Não conte os dias, faça os dias contarem.','— Muhammad Ali'],['Tudo parece impossível até que seja feito.','— Nelson Mandela'],['A criatividade é a inteligência se divertindo.','— Albert Einstein']];let x=q[Math.floor(Math.random()*q.length)];$('#quote').textContent=x[0];$('#quote').nextElementSibling.textContent=x[1];toast('Nova reflexão encontrada')};
$('#jobBtn').onclick=()=>openModal('Uma proposta chegou','Uma startup promissora quer você como líder de design. O salário é maior, mas o risco também.',()=>{addEvent('↗','Uma proposta de trabalho','Uma startup quer que você lidere o time de design.','blue');toast('Você adicionou uma nova possibilidade à sua história')});
$('#meetBtn').onclick=()=>openModal('Pessoa interessante','Na fila do café, alguém sorriu para você. Às vezes as melhores histórias começam assim.',()=>{toast('Uma nova conexão foi criada');addEvent('♡','Uma conexão inesperada','Você conheceu alguém novo no café.','pink');$('#relCount').textContent='5'});
$('#newLife').onclick=()=>openModal('Começar outra vida?','Isso vai criar uma nova história cheia de possibilidades. Sua jornada atual será arquivada.',()=>{toast('Sua próxima vida começa em breve...')});
$('#settingsBtn').onclick=()=>toast('Tudo salvo automaticamente no seu dispositivo');$('#closeModal').onclick=$('#modalCancel').onclick=()=>$('#modal').classList.add('hidden');
function setup(){renderEvents();$('#skills').innerHTML=[['Pensamento estratégico',78],['Pesquisa e empatia',91],['Liderança',62],['Comunicação',84]].map(x=>`<div class="skill"><div class="skill-top"><b>${x[0]}</b><span>${x[1]}/100</span></div><div class="skill-bar"><i style="width:${x[1]}%"></i></div></div>`).join('');$('#peopleGrid').innerHTML=[['Marina Costa','Melhor amiga','MC','#d79487',86],['Rafa Mendes','Parceiro de aventuras','RM','#749a94',72],['João Martins','Irmão','JM','#7899b2',94],['Lia Nakamura','Colega de trabalho','LN','#aa8fba',48]].map(p=>`<div class="person"><div class="person-avatar" style="background:${p[3]}">${p[2]}</div><div><h3>${p[0]}</h3><p>${p[1]}</p><div class="relationship"><i style="width:${p[4]}%"></i></div></div><button>Conversar</button></div>`).join('');$('#achievements').innerHTML=[['☀','Primeiro passo','Você começou sua jornada.'],['♧','Laços fortes','Construiu 5 relações significativas.'],['↗','Em ascensão','Foi promovido no trabalho.'],['✧','Mente aberta','Aprendeu 10 novas habilidades.'],['◉','Vida equilibrada','Manteve saúde e felicidade acima de 80.'],['?','Desconhecido','Explore mais para descobrir.']].map((x,i)=>`<div class="badge ${i===5?'locked':''}"><div class="badge-icon">${x[0]}</div><h3>${x[1]}</h3><p>${x[2]}</p></div>`).join('')};setup();

